-- Shipped v8 creation DDL from commit a6f1d212; synthetic legacy fixture values.
CREATE TABLE IF NOT EXISTS devices (id TEXT NOT NULL, user_id TEXT NOT NULL, name TEXT NOT NULL, last_seen_at TEXT NOT NULL, app_version TEXT, PRIMARY KEY(user_id, id));
CREATE TABLE IF NOT EXISTS workout_records (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, date TEXT NOT NULL, workout_type TEXT NOT NULL, category TEXT NOT NULL, exercise_name TEXT NOT NULL, duration_seconds INTEGER, total_volume_kg REAL NOT NULL DEFAULT 0, average_heart_rate REAL, created_at TEXT NOT NULL, is_backfilled INTEGER NOT NULL, backfilled_at TEXT, backfill_reason TEXT, updated_at TEXT NOT NULL, deleted_at TEXT, device_id TEXT NOT NULL, source_app TEXT NOT NULL, scope TEXT NOT NULL, metadata TEXT NOT NULL, contract_version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS meal_records (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, date TEXT NOT NULL, menu TEXT NOT NULL, calories INTEGER NOT NULL, protein_grams REAL NOT NULL, carbs_grams REAL, fat_grams REAL, created_at TEXT NOT NULL, is_backfilled INTEGER NOT NULL, backfilled_at TEXT, backfill_reason TEXT, updated_at TEXT NOT NULL, deleted_at TEXT, device_id TEXT NOT NULL, source_app TEXT NOT NULL, scope TEXT NOT NULL, metadata TEXT NOT NULL, contract_version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS weight_records (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, date TEXT NOT NULL, weight_kg REAL NOT NULL, created_at TEXT NOT NULL, is_backfilled INTEGER NOT NULL, backfilled_at TEXT, backfill_reason TEXT, updated_at TEXT NOT NULL, deleted_at TEXT, device_id TEXT NOT NULL, source_app TEXT NOT NULL, scope TEXT NOT NULL, metadata TEXT NOT NULL, contract_version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS workout_exercises (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, record_id TEXT NOT NULL, order_index INTEGER NOT NULL, exercise_id TEXT NOT NULL, exercise_name_snapshot TEXT NOT NULL, ui_part TEXT NOT NULL, primary_sub_part_snapshot TEXT, equipment_snapshot TEXT, record_type TEXT NOT NULL, memo TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT, device_id TEXT NOT NULL, contract_version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS workout_sets (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, workout_exercise_id TEXT NOT NULL, set_index INTEGER NOT NULL, target_reps INTEGER, actual_reps INTEGER, weight_kg REAL, volume_kg REAL, duration_seconds INTEGER, distance_meters REAL, rest_seconds INTEGER, assisted_weight_kg REAL, added_weight_kg REAL, is_completed INTEGER NOT NULL, rpe INTEGER, memo TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT, device_id TEXT NOT NULL, contract_version INTEGER NOT NULL DEFAULT 1);
CREATE INDEX IF NOT EXISTS devices_user_last_seen_at_idx ON devices(user_id, last_seen_at);
CREATE INDEX IF NOT EXISTS workout_records_user_scope_date_idx ON workout_records(user_id, scope, date);
CREATE INDEX IF NOT EXISTS workout_exercises_record_order_idx ON workout_exercises(record_id, order_index);
CREATE INDEX IF NOT EXISTS workout_sets_exercise_order_idx ON workout_sets(workout_exercise_id, set_index);
CREATE INDEX IF NOT EXISTS meal_records_user_scope_date_idx ON meal_records(user_id, scope, date);
CREATE INDEX IF NOT EXISTS weight_records_user_scope_date_idx ON weight_records(user_id, scope, date);
CREATE TABLE IF NOT EXISTS routines (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, name TEXT NOT NULL, is_default INTEGER NOT NULL, device_id TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT);
CREATE TABLE IF NOT EXISTS routine_exercises (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, routine_id TEXT NOT NULL, exercise_id TEXT NOT NULL, name_ko TEXT NOT NULL, ui_part TEXT NOT NULL, primary_sub_part TEXT NOT NULL, equipment TEXT NOT NULL, record_type TEXT NOT NULL, order_index INTEGER NOT NULL, device_id TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT);
CREATE INDEX IF NOT EXISTS routines_user_default_idx ON routines(user_id, is_default);
CREATE INDEX IF NOT EXISTS routine_exercises_routine_order_idx ON routine_exercises(routine_id, order_index);
CREATE TABLE IF NOT EXISTS cardio_sessions (record_id TEXT PRIMARY KEY, activity_type TEXT NOT NULL, status TEXT NOT NULL, started_at_epoch_ms INTEGER NOT NULL, last_resumed_at_epoch_ms INTEGER, active_duration_ms INTEGER NOT NULL DEFAULT 0, distance_meters REAL NOT NULL DEFAULT 0, accepted_point_count INTEGER NOT NULL DEFAULT 0, last_latitude REAL, last_longitude REAL, last_location_time_ms INTEGER, last_accuracy_meters REAL, gps_status TEXT NOT NULL DEFAULT 'searching', updated_at_epoch_ms INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS cardio_route_points (id INTEGER PRIMARY KEY AUTOINCREMENT, record_id TEXT NOT NULL, captured_at_epoch_ms INTEGER NOT NULL, latitude REAL NOT NULL, longitude REAL NOT NULL, accuracy_meters REAL NOT NULL, speed_mps REAL, segment_distance_meters REAL NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS cardio_sessions_status_started_idx ON cardio_sessions(status, started_at_epoch_ms);
CREATE INDEX IF NOT EXISTS cardio_route_points_record_time_idx ON cardio_route_points(record_id, captured_at_epoch_ms);
CREATE TABLE IF NOT EXISTS meal_menu_presets (id TEXT PRIMARY KEY, name TEXT NOT NULL COLLATE NOCASE UNIQUE, calories INTEGER, protein_grams REAL, carbs_grams REAL, fat_grams REAL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS meal_menu_presets_updated_idx ON meal_menu_presets(updated_at DESC);
CREATE TABLE IF NOT EXISTS nutrition_foods (id TEXT PRIMARY KEY, owner_id TEXT, name TEXT NOT NULL, kind TEXT NOT NULL, basis_amount REAL NOT NULL, basis_unit TEXT NOT NULL, calories_kcal REAL NOT NULL DEFAULT 0, protein_grams REAL NOT NULL DEFAULT 0, carbs_grams REAL NOT NULL DEFAULT 0, fat_grams REAL NOT NULL DEFAULT 0, source_type TEXT NOT NULL, source_reference TEXT, visibility TEXT NOT NULL DEFAULT 'private', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT);
CREATE TABLE IF NOT EXISTS nutrition_food_components (id TEXT PRIMARY KEY, owner_id TEXT, parent_food_id TEXT NOT NULL, child_food_id TEXT NOT NULL, quantity REAL NOT NULL, unit TEXT NOT NULL, order_index INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT);
CREATE TABLE IF NOT EXISTS meal_record_items (id TEXT PRIMARY KEY, user_id TEXT NOT NULL, meal_record_id TEXT NOT NULL, food_id TEXT, food_name_snapshot TEXT NOT NULL, quantity REAL NOT NULL, unit TEXT NOT NULL, calories REAL NOT NULL DEFAULT 0, protein_grams REAL NOT NULL DEFAULT 0, carbs_grams REAL NOT NULL DEFAULT 0, fat_grams REAL NOT NULL DEFAULT 0, order_index INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, deleted_at TEXT, device_id TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS nutrition_foods_owner_name_idx ON nutrition_foods(owner_id, name COLLATE NOCASE);
CREATE INDEX IF NOT EXISTS nutrition_foods_visibility_name_idx ON nutrition_foods(visibility, name COLLATE NOCASE);
CREATE INDEX IF NOT EXISTS nutrition_food_components_parent_order_idx ON nutrition_food_components(parent_food_id, order_index);
CREATE INDEX IF NOT EXISTS meal_record_items_meal_order_idx ON meal_record_items(meal_record_id, order_index);
